using System;
using System.Collections.Generic;
using System.Linq;

namespace ngakamodirimolema
{
    public sealed class RoutePlan
    {
        public List<(string From, string To, double Distance)> Edges { get; } = new();
        public double TotalDistance => Edges.Sum(e => e.Distance);
        public bool IsForest { get; init; }
    }

    public sealed class ServiceRequestService
    {
        private readonly List<ServiceRequest> _requests = new();
        private readonly object _sync = new();
        private int _nextSequence;
        private readonly AvlTree<int, ServiceRequest> _avl = new();
        private readonly BinarySearchTree<int, ServiceRequest> _bst = new();
        private readonly RedBlackTree<long, ServiceRequest> _chronological = new();
        private readonly MaxHeap<ServiceRequest> _heap;
        private readonly WeightedGraph<string> _related = new();
        private readonly WeightedGraph<string> _locations = new();
        private readonly Dictionary<string, List<ServiceRequest>> _categories = new(StringComparer.OrdinalIgnoreCase);
        private readonly Dictionary<string, string> _departments = new(StringComparer.OrdinalIgnoreCase) { ["Road"] = "Infrastructure > Roads", ["Water"] = "Infrastructure > Water and Sanitation", ["Sanitation"] = "Infrastructure > Water and Sanitation", ["Electricity"] = "Infrastructure > Electricity", ["Other"] = "Community Services" };
        public ServiceRequestService()
        {
            _heap = new MaxHeap<ServiceRequest>((a, b) => ((int)a.Priority).CompareTo((int)b.Priority) != 0 ? ((int)a.Priority).CompareTo((int)b.Priority) : b.SubmittedAt.CompareTo(a.SubmittedAt) != 0 ? b.SubmittedAt.CompareTo(a.SubmittedAt) : string.Compare(b.RequestId, a.RequestId, StringComparison.Ordinal));
            Seed();
        }
        public IReadOnlyList<ServiceRequest> GetAll() { lock (_sync) return _requests.OrderByDescending(x => x.SubmittedAt).ToList(); }
        public ServiceRequest? FindById(string id) { if (!int.TryParse(id.Trim().Replace("SR-", "", StringComparison.OrdinalIgnoreCase), out var n)) return null; lock (_sync) return _avl.TrySearch(n, out var r) ? r : null; }
        public IReadOnlyList<ServiceRequest> Search(string? keyword, string? status, string? category) { lock (_sync) return _requests.Where(r => (string.IsNullOrWhiteSpace(keyword) || $"{r.RequestId} {r.Title} {r.Description} {r.Location}".Contains(keyword.Trim(), StringComparison.OrdinalIgnoreCase)) && (string.IsNullOrWhiteSpace(status) || status == "All" || r.Status.ToString() == status) && (string.IsNullOrWhiteSpace(category) || category == "All" || r.Category == category)).OrderByDescending(r => r.SubmittedAt).ToList(); }
        public ServiceRequest Add(string title, string description, string category, string location, string attachmentPath = "") { lock (_sync) { var now = DateTime.Now; var r = New(++_nextSequence, title, description, category, location, ServiceRequestPriority.Medium, ServiceRequestStatus.Submitted, now, attachmentPath); AddInternal(r); return r; } }
        public bool AdvanceStatus(ServiceRequest r) { lock (_sync) { if (r.Status == ServiceRequestStatus.Resolved) return false; r.Status = (ServiceRequestStatus)((int)r.Status + 1); r.UpdatedAt = DateTime.Now; r.StatusHistory.Add(new() { Timestamp = r.UpdatedAt, Status = r.Status, Note = "Status advanced by service desk." }); RebuildIndexes(); return true; } }
        public ServiceRequest? NextUrgent() { lock (_sync) { while (_heap.Count > 0) { var r = _heap.Peek(); if (r.Status == ServiceRequestStatus.Resolved) { _heap.Extract(); continue; } return r; } return null; } }
        public ServiceRequest? ProcessNext() { lock (_sync) { var r = NextUrgent(); if (r == null) return null; _heap.Extract(); if (r.Status == ServiceRequestStatus.Submitted) r.Status = ServiceRequestStatus.InProgress; else if (r.Status == ServiceRequestStatus.Acknowledged) r.Status = ServiceRequestStatus.InProgress; r.UpdatedAt = DateTime.Now; r.StatusHistory.Add(new() { Timestamp = r.UpdatedAt, Status = r.Status, Note = "Urgent request assigned to a crew." }); RebuildIndexes(); return r; } }
        public IReadOnlyList<string> RelatedBfs(ServiceRequest r) => _related.BreadthFirst(r.RequestId); public IReadOnlyList<string> RelatedDfs(ServiceRequest r) => _related.DepthFirst(r.RequestId);
        public RoutePlan PlanRoute() { lock (_sync) { var open = _requests.Where(r => r.Status != ServiceRequestStatus.Resolved).Select(r => r.Location).Distinct().ToList(); var edges = _locations.MinimumSpanningForest(open); return new RoutePlan { IsForest = edges.Count < Math.Max(0, open.Count - 1), Edges = { } }.With(edges); } }
        public string Insights() => $"Requests: {_requests.Count}\r\nAVL height: {_avl.Height}, rotations: {_avl.RotationCount}, last AVL comparisons: {_avl.LastComparisons}\r\nBST height (sequential keys): {_bst.Height}\r\nChronological index entries: {_chronological.InOrder().Count()} (recolour operations: {_chronological.ColourChanges})\r\nUrgent heap count: {_heap.Count}\r\nAVL lookup is O(log n); sequential BST lookup can degrade to O(n).";
        public string CategoryTreeText() => string.Join(Environment.NewLine, _categories.OrderBy(x => x.Key).Select(x => $"Municipal Services\r\n  {_departments[x.Key]}\r\n    {x.Key} ({x.Value.Count})"));
        public bool SelfCheck() { var avl = new AvlTree<int, int>(); for (var i = 1; i <= 30; i++) avl.Insert(i, i); return avl.Height <= 6 && avl.TrySearch(20, out _); }
        private void AddInternal(ServiceRequest r) { _requests.Add(r); _nextSequence = Math.Max(_nextSequence, r.SequenceNumber); RebuildIndexes(); }
        private void RebuildIndexes() { _avl.GetType(); ClearIndexes(); foreach (var r in _requests) { _avl.Insert(r.SequenceNumber, r); _bst.Insert(r.SequenceNumber, r); _chronological.Insert(r.SubmittedAt.Ticks * 1000 + r.SequenceNumber, r); if (r.Status != ServiceRequestStatus.Resolved) _heap.Add(r); if (!_categories.TryGetValue(r.Category, out var list)) _categories[r.Category] = list = new(); if (!list.Contains(r)) list.Add(r); _related.AddNode(r.RequestId); _locations.AddNode(r.Location); } foreach (var a in _requests) foreach (var b in _requests.Where(x => x.SequenceNumber > a.SequenceNumber && (x.Location.Equals(a.Location, StringComparison.OrdinalIgnoreCase) || x.Category.Equals(a.Category, StringComparison.OrdinalIgnoreCase)))) _related.AddEdge(a.RequestId, b.RequestId); foreach (var e in new[] { ("Mahikeng", "Zeerust", 70d), ("Mahikeng", "Lichtenburg", 65d), ("Lichtenburg", "Delareyville", 55d), ("Delareyville", "Ottosdal", 45d), ("Zeerust", "Groot Marico", 65d), ("Groot Marico", "Mahikeng", 95d), ("Lichtenburg", "Coligny", 35d) }) _locations.AddEdge(e.Item1, e.Item2, e.Item3); }
        private void ClearIndexes() { while (_heap.Count > 0) _heap.Extract(); _categories.Clear(); }
        private static ServiceRequest New(int n, string t, string d, string c, string l, ServiceRequestPriority p, ServiceRequestStatus s, DateTime date, string attachment = "") { var r = new ServiceRequest { SequenceNumber = n, Title = t, Description = d, Category = c, Location = l, Priority = p, Status = s, SubmittedAt = date, UpdatedAt = date, AssignedDepartment = c == "Road" ? "Roads & Stormwater" : c == "Electricity" ? "Electrical Services" : "Water" == c || c == "Sanitation" ? "Water & Sanitation" : "Community Services", AttachmentPath = attachment }; for (var i = 0; i <= (int)s; i++) r.StatusHistory.Add(new() { Timestamp = date.AddDays(i), Status = (ServiceRequestStatus)i, Note = i == 0 ? "Request submitted." : "Workflow stage completed." }); return r; }
        private void Seed() { var data = new[] { ("Pothole on main road", "Deep pothole affecting taxis", "Road", "Mahikeng", ServiceRequestPriority.High, ServiceRequestStatus.InProgress), ("Burst water pipe", "Water running into the street", "Water", "Mahikeng", ServiceRequestPriority.Critical, ServiceRequestStatus.Acknowledged), ("Broken streetlight", "Dark intersection", "Electricity", "Zeerust", ServiceRequestPriority.High, ServiceRequestStatus.Submitted), ("Sewer overflow", "Overflow near homes", "Sanitation", "Lichtenburg", ServiceRequestPriority.Critical, ServiceRequestStatus.InProgress), ("Illegal dumping", "Rubbish dumped beside river", "Other", "Delareyville", ServiceRequestPriority.Medium, ServiceRequestStatus.Submitted), ("Missed refuse collection", "Collection missed twice", "Other", "Ottosdal", ServiceRequestPriority.Medium, ServiceRequestStatus.Resolved), ("Road shoulder erosion", "Unsafe shoulder after rain", "Road", "Coligny", ServiceRequestPriority.High, ServiceRequestStatus.Acknowledged), ("Leaking hydrant", "Hydrant leaks continuously", "Water", "Groot Marico", ServiceRequestPriority.Medium, ServiceRequestStatus.Submitted), ("Streetlight outage", "Three lights out", "Electricity", "Mahikeng", ServiceRequestPriority.High, ServiceRequestStatus.Resolved), ("Blocked drain", "Storm drain blocked", "Sanitation", "Zeerust", ServiceRequestPriority.Medium, ServiceRequestStatus.Submitted), ("Pothole near school", "Large road defect", "Road", "Zeerust", ServiceRequestPriority.Critical, ServiceRequestStatus.Acknowledged), ("Illegal dumping site", "Building rubble dumped", "Other", "Lichtenburg", ServiceRequestPriority.High, ServiceRequestStatus.InProgress), ("Low water pressure", "Pressure drops daily", "Water", "Delareyville", ServiceRequestPriority.Medium, ServiceRequestStatus.Resolved), ("Sewer manhole damage", "Open manhole requires repair", "Sanitation", "Ottosdal", ServiceRequestPriority.Critical, ServiceRequestStatus.Submitted), ("Refuse bin shortage", "Bins needed for ward", "Other", "Coligny", ServiceRequestPriority.Low, ServiceRequestStatus.Submitted), ("Cable fault", "Cable exposed", "Electricity", "Groot Marico", ServiceRequestPriority.High, ServiceRequestStatus.InProgress), ("Pothole repairs", "Multiple potholes", "Road", "Mahikeng", ServiceRequestPriority.Medium, ServiceRequestStatus.Submitted), ("Pipe leak", "Leak by clinic", "Water", "Mahikeng", ServiceRequestPriority.High, ServiceRequestStatus.Resolved), ("Streetlight repair", "Light flickers at night", "Electricity", "Lichtenburg", ServiceRequestPriority.Medium, ServiceRequestStatus.Submitted), ("Sewer blockage", "Sewer backs up", "Sanitation", "Delareyville", ServiceRequestPriority.High, ServiceRequestStatus.Acknowledged), ("Waste collection route", "Collection vehicle missed route", "Other", "Zeerust", ServiceRequestPriority.Low, ServiceRequestStatus.Submitted), ("Road markings", "Faded crossing markings", "Road", "Ottosdal", ServiceRequestPriority.Low, ServiceRequestStatus.Resolved), ("Water valve", "Valve cannot close", "Water", "Coligny", ServiceRequestPriority.High, ServiceRequestStatus.Submitted), ("Illegal dumping", "Household waste dumped", "Other", "Groot Marico", ServiceRequestPriority.Medium, ServiceRequestStatus.InProgress), ("Power outage", "Supply interruption", "Electricity", "Mahikeng", ServiceRequestPriority.Critical, ServiceRequestStatus.Submitted), ("Blocked sewer", "Overflow reported", "Sanitation", "Zeerust", ServiceRequestPriority.High, ServiceRequestStatus.Resolved), ("Road crack", "Crack widening", "Road", "Lichtenburg", ServiceRequestPriority.Medium, ServiceRequestStatus.Submitted), ("Water main", "Main line damaged", "Water", "Delareyville", ServiceRequestPriority.Critical, ServiceRequestStatus.Acknowledged) }; var i = 0; foreach (var x in data) AddInternal(New(++i, x.Item1, x.Item2, x.Item3, x.Item4, x.Item5, x.Item6, DateTime.Today.AddDays(-i))); }
    }
    internal static class RoutePlanExtensions { public static RoutePlan With(this RoutePlan p, IEnumerable<(string From, string To, double Weight)> edges) { foreach (var e in edges) p.Edges.Add((e.From, e.To, e.Weight)); return p; } }
}
